mapper.select:
select ftp.FINPROD_ID as finprodId, /*交易编号*/ ftp.FINPROD_TYPE2 as finprodType2, /*期权标的类型*/ fpt.TYPE_6 as type6, /*资产类型*/ to_char(ftp.VDATE, 'yyyy-MM-dd') as vdate, /*起息日*/ to_char(ftp.MDATE, 'yyyy-MM-dd') as mdate, /*到期日*/ ftp.EXC_PS as extPs, /*交易方向*/ ftp.CCY as ccy, /*币种*/ ftp.TERM as term, /*期限*/ ftp.CONTRACT_NO as contractNo, /*合同编号*/ ftp.CONTRACT_NAME as contractName, /*合同名称*/ ftp.CALENDAR_ID as calendarId, /*交易日历*/ mci.CALENDAR_NAME as calendarName, /*日历名称*/ ftp.PRIN as prin, /*数量*/ ftp.TRADE_MARKET as tradeMarket, /*交易场所*/ ftpa.REGIST_ORG as registOrg, /*登记托管机构*/ ftpa.OPT_FEE_PAY_TYPE as optFeePayType, /*期权费类型*/ ftpa.OPT_FEE_RATE as optFeeRate /*期权费率*/ from FIN_TRADE_PRODUCT ftp left join FIN_PRODUCT_TYPE fpt on ftp.FINPROD_ID = fpt.FINPROD_ID left join FIN_TRADE_PRODUCT_ADD ftpa on ftp.FINPROD_ID = ftpa.FINPROD_ID left join MST_CALENDAR_INFO mci on mci.CALENDAR_ID = ftp.CALENDAR_ID where ftp.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F35}
AND ftp.FINPROD_ID = #{finprodId}
AND to_char(ftp.VDATE, 'yyyy-MM-dd') = #{vdate}
AND ftp.EXC_PS = #{extPs}
AND ftp.CCY = #{ccy}
AND ftpa.OPT_FEE_PAY_TYPE = #{optFeePayType}
